package org.sleepwell.app;

import android.app.Activity;
import android.content.*;
import android.content.pm.PackageManager;
import android.net.Uri;
import android.os.*;
import android.provider.Settings;
import android.widget.*;
import java.util.*;

/** Pairing controls only. Neither opening nor granting permission starts a recording or radio search. */
public final class PairMotionActivity extends Activity {
    private final Handler main=new Handler(Looper.getMainLooper());private boolean resumed,filter;private String issue="",last="";
    @Override public void onCreate(Bundle saved){super.onCreate(saved);RecordUi.review(this);if(saved!=null){filter=saved.getBoolean("filter");issue=saved.getString("issue","");}if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,this::finish);render();}
    private void render(){PairMotionRuntime.State state=PairMotionRuntime.state();LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);RecordUi.header(body,"Pair movement tracking",this::finish);Design.space(body,14);Design.text(body,"Two phones, separate recordings",21,600,Design.INK);Design.space(body,7);Design.text(body,"Each person starts Phone movement manually. Pairing shares movement averages, not audio, and cannot start or control the other phone.",13,400,Design.MUTED);Design.space(body,16);
        if(state!=null&&state.busy){Design.text(body,state.connected?"Paired":"Pairing",22,600,Design.INK);Design.text(body,state.message,14,500,Design.BROWN);if(state.confirm){Design.space(body,18);Design.text(body,"Does this code match on BOTH phones?",14,600,Design.INK);TextView digits=Design.text(body,state.code,42,700,Design.INK);digits.setGravity(android.view.Gravity.CENTER);Design.text(body,state.name,13,400,Design.MUTED);String link=state.link,code=state.code;Design.button(body,"The codes match",true,()->{if(resumed&&hasWindowFocus()){PairMotionRuntime.confirm(link,code);render();}});Design.button(body,"Reject connection",false,()->{PairMotionRuntime.stop(link);render();});}else if(!state.found.isEmpty()){Design.space(body,12);Design.text(body,"Choose the phone to pair",16,600,Design.INK);for(PairMotionRuntime.Peer peer:state.found)Design.button(body,peer.name,false,()->{PairMotionRuntime.connect(peer.id);render();});}if(state.connected){Design.space(body,16);metric(body,"This phone · raw",state.own);metric(body,"Other phone · fresh aligned",state.peer);metric(body,"Experimental filtered value",state.filtered);Design.text(body,state.uncertainty<0?"Clock alignment unavailable · raw fallback":"Clock alignment uncertainty ≤ "+state.uncertainty+" ms",12,400,Design.MUTED);Design.text(body,state.filter?"Filter was explicitly enabled for this pairing. Missing or weak matches use original movement.":"Filter off. Both original movement streams are saved separately.",12,400,Design.MUTED);}LinearLayout footer=RecordUi.footer(body);Design.button(footer,"Stop pairing",true,()->{PairMotionRuntime.stop(state.link);render();});Design.button(footer,"Back to tracking",false,this::finish);
        }else{if(state!=null){Design.text(body,state.message,14,500,Design.BROWN);Design.space(body,14);}String prerequisite=PairMotionRuntime.prerequisite(this);Design.toggle(body,"Experimental movement filter","Reduce strongly shared movement for this phone’s smart-wake estimate only. Both raw streams stay saved.",filter,on->{filter=on;});Design.space(body,10);Design.text(body,"The filter needs at least a minute of well-aligned variation. It cannot reliably identify which person moved or measure sleep stages.",12,400,Design.MUTED);Design.space(body,14);if(!prerequisite.isEmpty())Design.text(body,prerequisite,13,500,Design.BROWN);if(!PairMotionRuntime.missingPermissions(this).isEmpty()){Design.button(body,"Allow nearby discovery",false,this::permissions);Design.button(body,"App permission settings",false,()->startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName()))));}if(TrackingService.pairManual()==null)Design.button(body,"Open tracking setup",false,()->startActivity(RecordUi.intent(this,TrackingActivity.class)));Design.button(body,"Host pairing",true,()->begin(true)).setEnabled(prerequisite.isEmpty());Design.button(body,"Find phone",false,()->begin(false)).setEnabled(prerequisite.isEmpty());}
        if(!issue.isEmpty()){Design.space(body,10);Design.text(body,issue,13,500,Design.BROWN);}Design.space(body,16);PlanActivity.detail(body,"report","Saved paired readings","Separate raw streams and alignment quality",null,()->startActivity(RecordUi.intent(this,PairMotionSavedActivity.class)));Design.space(body,12);Design.text(body,"Nearby uses encrypted Google Play services transport over nearby radios. Google Usage & diagnostics settings control its diagnostic collection. Pause, end or process loss stops pairing; connect again explicitly.",11,400,Design.MUTED);last=signature(PairMotionRuntime.state());}
    private void begin(boolean host){if(!resumed||!hasWindowFocus())return;try{issue="";PairMotionRuntime.begin(this,host,filter);}catch(RuntimeException error){issue=error.getMessage()==null?"Nearby pairing is unavailable.":error.getMessage();}render();}
    private void permissions(){if(!resumed||!hasWindowFocus())return;List<String> permissions=new ArrayList<>(PairMotionRuntime.missingPermissions(this));if(permissions.contains(android.Manifest.permission.ACCESS_FINE_LOCATION)&&!permissions.contains(android.Manifest.permission.ACCESS_COARSE_LOCATION))permissions.add(android.Manifest.permission.ACCESS_COARSE_LOCATION);if(!permissions.isEmpty())requestPermissions(permissions.toArray(new String[0]),681);}
    @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] grants){super.onRequestPermissionsResult(request,permissions,grants);if(request==681){issue=PairMotionRuntime.missingPermissions(this).isEmpty()?"Nearby permission allowed. Choose Host pairing or Find phone when ready.":"Nearby permission was not fully allowed. Pairing is off; ordinary tracking still works.";render();}}
    private void metric(LinearLayout body,String label,Double value){PlanActivity.detail(body,"wave",label,null,value==null?"Unavailable":String.format(Locale.ROOT,"%.3f",value),null);}
    private String signature(PairMotionRuntime.State state){return state==null?"none:"+(TrackingService.pairManual()!=null):state.busy+":"+state.connected+":"+state.message+":"+state.code+":"+state.found.stream().map(p->p.id).collect(java.util.stream.Collectors.joining(","))+":"+state.own+":"+state.peer+":"+state.filtered+":"+state.uncertainty;}
    private final Runnable poll=new Runnable(){@Override public void run(){if(!resumed)return;String current=signature(PairMotionRuntime.state());if(!current.equals(last))render();main.postDelayed(this,1000);}};
    @Override protected void onResume(){super.onResume();resumed=true;render();main.post(poll);}@Override protected void onPause(){resumed=false;main.removeCallbacks(poll);super.onPause();}@Override protected void onDestroy(){main.removeCallbacks(poll);super.onDestroy();}@Override protected void onSaveInstanceState(Bundle saved){super.onSaveInstanceState(saved);saved.putBoolean("filter",filter);saved.putString("issue",issue);}@Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);}
}
